import type { Localized, Lesson, Flashcard, Question, Activity, Lab, ExternalResource } from '../types'; import type { WeekContent } from '../weekContent';
const L=(en:string,es:string,pt:string):Localized=>({en,es,pt}); const X=L; type Ex={title:Localized;prompt:Localized;hint:Localized;solution:Localized;level:1|2|3};
type CheckData=[Localized,Localized,Localized,Localized,Localized,string,Localized,Localized,Localized];
const lesson=(id:string,title:Localized,body:Localized[],analogy:Localized,takeaways:Localized[],c:CheckData,ex:Ex[],code?:{language:string;caption:Localized;source:string}):Lesson=>({id,title,minutes:25,body,analogy,takeaways,check:{question:c[0],options:[c[1],c[2],c[3],c[4]],answer:Number(c[5]),explanation:c[6]},pitfalls:[{mistake:c[7],fix:c[8]}],exercises:ex.map((e,i)=>({id:`${id}-ex${i+1}`,...e})),...(code?{code}:{})});
const card=(id:string,l:string,f:Localized,b:Localized,k:'concept'|'distinction'='concept'):Flashcard=>({id,lessonId:l,front:f,back:b,kind:k});const mc=(id:string,l:string,p:Localized,o:Localized[],a:number,e:Localized):Question=>({id,lessonId:l,type:'multiple-choice',prompt:p,options:o,answer:a,explanation:e});const tf=(id:string,l:string,p:Localized,a:boolean,e:Localized):Question=>({id,lessonId:l,type:'true-false',prompt:p,options:[X('True','Verdadero','Verdadeiro'),X('False','Falso','Falso')],answer:a?0:1,explanation:e});const fill=(id:string,l:string,p:Localized,a:string[],e:Localized):Question=>({id,lessonId:l,type:'fill-blank',prompt:p,accepted:a,explanation:e});const short=(id:string,l:string,p:Localized,a:string[],e:Localized):Question=>({id,lessonId:l,type:'short-answer',prompt:p,accepted:a,explanation:e});const matching=(id:string,l:string,p:Localized,left:Localized[],right:Localized[],answer:number[],e:Localized):Question=>({id,lessonId:l,type:'matching',prompt:p,left,right,answer,explanation:e});const order=(id:string,l:string,t:Localized,p:Localized,items:Localized[],e:Localized):Activity=>({id,lessonId:l,kind:'order',title:t,prompt:p,items,explanation:e});const classify=(id:string,l:string,t:Localized,p:Localized,buckets:Localized[],items:{text:Localized;bucket:number}[],e:Localized):Activity=>({id,lessonId:l,kind:'classify',title:t,prompt:p,buckets,items,explanation:e});const lab=(id:string,t:Localized,g:Localized,steps:{title:Localized;expected:Localized}[]):Lab=>({id,kind:'design',level:2,title:t,goal:g,minutes:40,steps:steps.map((s,i)=>({id:`${id}-s${i+1}`,title:s.title,commands:[],expected:s.expected}))});const res=(id:string,title:string,url:string,n:Localized):ExternalResource=>({id,title,url,kind:'article',verifiedOn:'2026-11-04',note:n});
const lessons:Lesson[]=[
lesson('hist8-l1',X('Choose an original historical question','Elige una pregunta histórica original','Escolha uma pergunta histórica original'),[
X('A focused research project asks one answerable question about a change in software engineering or computing. Possible topics include a language design, a project-management idea, a software business model, a safety-critical system, open-source coordination, or a technology shift. Choose an angle that lets you explain why something changed and what effects followed.','Un proyecto enfocado plantea una pregunta respondible sobre un cambio en ingeniería de software o computación. Puedes estudiar un lenguaje, una idea de gestión, un modelo de negocio, un sistema crítico, coordinación de código abierto o una transformación tecnológica. Elige un ángulo que explique por qué cambió algo y qué consecuencias hubo.','Um projeto focado faz uma pergunta respondível sobre mudança em engenharia de software ou computação. Você pode estudar linguagem, ideia de gestão, modelo de negócio, sistema crítico, coordenação de código aberto ou transformação tecnológica. Escolha ângulo que explique por que algo mudou e quais efeitos ocorreram.'),
X('A topic is not yet a research question. “The history of AI” is too broad for a short essay; “How did software testing practices respond to the reliability demands of spaceflight?” gives a bounded problem and invites evidence. A useful question names a time or transition, a subject, and a relationship to investigate.','Un tema todavía no es una pregunta. “La historia de la IA” es demasiado amplio; “¿Cómo respondieron las pruebas de software a las exigencias de confiabilidad de los vuelos espaciales?” acota el problema y pide evidencia. Una buena pregunta delimita época o transición, tema y relación.','Tema ainda não é pergunta de pesquisa. “História da IA” é amplo; “Como testes de software responderam às exigências de confiabilidade de voos espaciais?” delimita problema e pede evidências. Boa pergunta indica período ou transição, tema e relação a investigar.')],
X('A project question is a camera frame: wide enough to show context, narrow enough to make the subject legible.','La pregunta es el encuadre de una cámara: muestra contexto y mantiene el tema visible.','A pergunta é o enquadramento de uma câmera: mostra contexto e mantém assunto legível.'),
[X('Choose a topic that can be answered with evidence within the available time.','Elige un tema que puedas responder con evidencia en el tiempo disponible.','Escolha tema que possa ser respondido com evidências no tempo disponível.'),X('A research question guides source selection and structure.','La pregunta guía la selección de fuentes y la estructura.','A pergunta orienta seleção de fontes e estrutura.')],
[X('Which is the best short-project question?','¿Cuál es la mejor pregunta para un proyecto corto?','Qual é a melhor pergunta para projeto curto?'),X('How did one specific change in language design affect the work of its intended users?','¿Cómo afectó un cambio concreto de diseño de lenguaje a sus usuarios previstos?','Como mudança específica de projeto de linguagem afetou o trabalho dos usuários previstos?'),X('What is all of computing?','¿Qué es toda la computación?','O que é toda a computação?'),X('Which inventor is the greatest?','¿Quién es el mejor inventor?','Qual inventor é o maior?'),X('Why is modern technology good?','¿Por qué la tecnología moderna es buena?','Por que tecnologia moderna é boa?'),'0',X('The question names a bounded change, an affected group, and a relationship to investigate.','La pregunta nombra un cambio acotado, un grupo afectado y una relación.','A pergunta nomeia mudança delimitada, grupo afetado e relação a investigar.'),X('Choosing a topic too broad for the project format.','Elegir un tema demasiado amplio.','Escolher tema amplo demais.'),X('Limit by period, technology, community, and one central question.','Limita época, tecnología, comunidad y una pregunta central.','Limite período, tecnologia, comunidade e uma pergunta central.')],
[{title:X('Narrow a topic','Acota un tema','Delimite um tema'),prompt:X('Turn “open source” into a question for a short essay or timeline.','Convierte “código abierto” en una pregunta para ensayo o cronología.','Transforme “código aberto” em pergunta para ensaio ou linha do tempo.'),hint:X('Pick a period, project, and effect to examine.','Elige época, proyecto y efecto.','Escolha período, projeto e efeito.'),solution:X('Example: How did the Linux kernel’s early collaborative development change expectations about who could contribute to operating-system software?','Ejemplo: ¿Cómo cambió el desarrollo colaborativo temprano del kernel Linux quién podía contribuir a sistemas operativos?','Exemplo: Como o desenvolvimento colaborativo inicial do kernel Linux mudou expectativas sobre quem podia contribuir a software de sistema?'),level:2},{title:X('Check answerability','Comprueba si se puede responder','Verifique se é respondível'),prompt:X('What makes a question answerable in one short project?','¿Qué hace que una pregunta pueda responderse en un proyecto breve?','O que torna uma pergunta respondível em projeto curto?'),hint:X('Consider scope and available public evidence.','Considera alcance y evidencia pública disponible.','Considere escopo e evidências públicas disponíveis.'),solution:X('It has a clear scope, available reliable sources, and a claim that can be supported in a few sections or a compact timeline.','Tiene alcance claro, fuentes confiables disponibles y una afirmación sustentable en pocas secciones o una cronología breve.','Tem escopo claro, fontes confiáveis disponíveis e alegação que pode ser sustentada em poucas seções ou linha do tempo curta.'),level:1}]),
lesson('hist8-l2',X('Find, compare, and verify sources','Busca, compara y verifica fuentes','Encontre, compare e verifique fontes'),[
X('Start with reputable public sources such as museum collections and timelines, professional-society histories, archival documents, standards, and firsthand technical publications. A secondary source can explain context; a primary source can show what a person or group recorded at the time. Use both when possible, and be clear about what each source can establish.','Empieza con museos y cronologías, historias de sociedades profesionales, archivos, estándares y publicaciones técnicas originales. Una fuente secundaria explica contexto; una primaria muestra lo que una persona o grupo registró en su época. Usa ambas cuando sea posible y aclara qué demuestra cada una.','Comece com museus e linhas do tempo, histórias de sociedades profissionais, arquivos, padrões e publicações técnicas originais. Fonte secundária explica contexto; fonte primária mostra o que uma pessoa ou grupo registrou na época. Use ambas quando possível e deixe claro o que cada uma sustenta.'),
X('Check author or institution, publication date, evidence, references, and purpose. Verify dates and technical claims in at least two sources when practical. Record the title, publisher, URL, date accessed, and the exact claim supported while taking notes in your own words. A link alone is not evidence unless it directly supports the sentence beside it.','Revisa autor u organización, fecha, evidencia, referencias y propósito. Verifica fechas y afirmaciones técnicas en dos fuentes cuando sea posible. Registra título, entidad, URL, fecha de consulta y afirmación que respalda; toma notas con tus propias palabras. Un enlace no demuestra nada si no apoya la oración concreta.','Confira autor ou organização, data, evidências, referências e finalidade. Verifique datas e afirmações técnicas em duas fontes quando possível. Registre título, entidade, URL, acesso e afirmação apoiada; anote com suas palavras. Link sozinho não prova nada se não apoiar a frase específica.')],
X('A careful reporter checks a witness account against records and another independent account before drawing a conclusion.','Una persona investigadora compara un testimonio con registros y otra fuente antes de concluir.','Uma pessoa pesquisadora compara depoimento a registros e outra fonte antes de concluir.'),
[X('Primary and secondary sources play different roles.','Las fuentes primarias y secundarias cumplen funciones distintas.','Fontes primárias e secundárias têm funções distintas.'),X('Citations should support specific claims, not merely decorate a bibliography.','Las citas deben respaldar afirmaciones concretas.','Citações devem apoiar alegações específicas, não apenas compor bibliografia.')],
[X('What is a useful way to verify a date?','¿Cómo conviene verificar una fecha?','Como verificar uma data?'),X('Compare reputable independent sources and check what event each date describes.','Compara fuentes confiables e identifica qué evento describe cada fecha.','Compare fontes confiáveis e confira qual evento cada data descreve.'),X('Repeat the first date seen online.','Repetir la primera fecha vista.','Repetir a primeira data encontrada.'),X('Use a search snippet only.','Usar solo un fragmento de búsqueda.','Usar apenas trecho do buscador.'),X('Guess from a person’s age.','Adivinar por la edad de alguien.','Adivinhar pela idade da pessoa.'),'0',X('Sources may refer to conception, announcement, first test, release, or standardization.','Las fuentes pueden referirse a propuesta, anuncio, primera prueba, publicación o estándar.','Fontes podem referir-se à concepção, anúncio, primeiro teste, lançamento ou padronização.'),X('Copying a fact without noting which event the date identifies.','Copiar una fecha sin saber qué evento identifica.','Copiar data sem saber que evento ela identifica.'),X('Record the event, date, and supporting source together.','Registra juntos evento, fecha y fuente.','Registre evento, data e fonte em conjunto.')],
[{title:X('Audit a claim','Audita una afirmación','Audite uma alegação'),prompt:X('A source says “the first version appeared in 1991.” What should you clarify before using the date?','Una fuente dice “la primera versión apareció en 1991”. ¿Qué debes aclarar?','Uma fonte diz “a primeira versão surgiu em 1991”. O que esclarecer antes de usar a data?'),hint:X('What does “appeared” mean?','¿Qué significa “apareció”?','O que significa “surgiu”?'),solution:X('Identify whether it means proposal, prototype, public announcement, release, or first deployment; find a source that names that event.','Aclara si significa propuesta, prototipo, anuncio, lanzamiento o despliegue; busca fuente que identifique el evento.','Identifique se significa proposta, protótipo, anúncio, lançamento ou implantação; busque fonte que nomeie o evento.'),level:2},{title:X('Choose a source pair','Elige un par de fuentes','Escolha par de fontes'),prompt:X('Choose a useful primary and secondary source pair for a project on the Agile Manifesto.','Elige una fuente primaria y otra secundaria para estudiar el Manifiesto Ágil.','Escolha uma fonte primária e secundária para projeto sobre Manifesto Ágil.'),hint:X('Look for the text itself and a historical account.','Busca el texto y una reseña histórica.','Procure o texto e um relato histórico.'),solution:X('Use the manifesto and its official history as primary accounts, then compare with a professional-society or scholarly history for context.','Usa el manifiesto y su historia oficial como fuentes primarias, y compáralos con una historia profesional.','Use manifesto e história oficial como fontes primárias e compare com relato histórico de sociedade profissional.') ,level:2}]),
lesson('hist8-l3',X('Build a claim and a clear structure','Construye una tesis y una estructura clara','Construa argumento e estrutura clara'),[
X('A short history essay needs a defensible central claim, not just a topic summary. The claim should answer the research question and explain a relationship: for example, how a technical constraint encouraged a design choice, or how a business model shaped access to software. Each section should contribute evidence and reasoning to that claim.','Un ensayo histórico breve necesita una afirmación defendible, no solo resumen. Debe responder la pregunta y explicar una relación: por ejemplo, cómo una restricción técnica impulsó una decisión o cómo un modelo comercial condicionó el acceso. Cada sección aporta evidencia y razonamiento.','Ensaio histórico curto precisa de argumento defensável, não apenas resumo. O argumento responde à pergunta e explica relação: por exemplo, como restrição técnica incentivou decisão ou como modelo comercial moldou acesso. Cada seção contribui com evidências e raciocínio.'),
X('A timeline presentation needs a narrative too. Group milestones into phases, label what changed, and include a short explanation of cause, effect, and uncertainty. Avoid filling slides with dates. Use concise labels and source notes close to each milestone so viewers can trace the claim.','Una presentación cronológica también necesita narrativa. Agrupa hitos, indica qué cambió y explica causa, efecto e incertidumbre. Evita llenar diapositivas de fechas. Usa etiquetas breves y fuentes junto a cada hito para poder verificarlo.','Apresentação cronológica também precisa de narrativa. Agrupe marcos, indique o que mudou e explique causa, efeito e incerteza. Evite encher slides de datas. Use rótulos breves e fontes junto a cada marco para permitir conferência.')],
X('A trail map is more useful when it shows which route leads to the destination, not only a list of landmarks.','Un mapa de senderos sirve más si muestra la ruta al destino y no solo una lista de lugares.','Mapa de trilha é mais útil quando mostra rota ao destino, não só lista de marcos.'),
[X('A claim answers the question and guides the structure.','Una tesis responde la pregunta y guía la estructura.','Argumento responde pergunta e orienta estrutura.'),X('A timeline should explain transitions, not only display dates.','Una cronología explica transiciones, no solo fechas.','Linha do tempo explica transições, não apenas mostra datas.')],
[X('What belongs in the central claim?','¿Qué debe incluir la tesis central?','O que deve conter o argumento central?'),X('An answer to the question and an explainable relationship supported by evidence.','Una respuesta a la pregunta y una relación explicable con evidencia.','Resposta à pergunta e relação explicável apoiada por evidências.'),X('A list of all dates you found.','Una lista de todas las fechas encontradas.','Lista de todas as datas encontradas.'),X('A personal opinion without sources.','Una opinión sin fuentes.','Opinião sem fontes.'),X('A quotation from every source.','Una cita de cada fuente.','Uma citação de cada fonte.'),'0',X('A claim gives the project direction and can be tested against evidence.','La tesis da dirección al proyecto y se contrasta con evidencia.','Argumento dá direção ao projeto e pode ser conferido com evidências.'),X('Writing the project as a sequence of unrelated facts.','Escribir hechos sin relación.','Escrever fatos sem relação entre si.'),X('Use transitions to show why one development changed what came next.','Explica por qué un avance influyó en el siguiente.','Explique por que um avanço influenciou o seguinte.')],
[{title:X('Draft a thesis','Redacta una tesis','Esboce argumento'),prompt:X('Write a tentative claim for a project about stored-program computers.','Escribe una tesis provisional sobre computadoras de programa almacenado.','Escreva argumento provisório sobre computadores de programa armazenado.'),hint:X('Connect a technical change to work or users.','Relaciona un cambio técnico con trabajo o usuarios.','Conecte mudança técnica ao trabalho ou aos usuários.'),solution:X('Example: Storing instructions in memory made it easier to change a computer’s task, shifting reprogramming from physical rewiring toward loading and revising programs.','Ejemplo: guardar instrucciones en memoria facilitó cambiar de tarea y movió la reprogramación del cableado a la carga y revisión de programas.','Exemplo: armazenar instruções na memória facilitou mudar tarefas e deslocou reprogramação de cabos para carregamento e revisão de programas.'),level:2},{title:X('Outline a timeline story','Organiza una narrativa cronológica','Estruture narrativa cronológica'),prompt:X('Group six events into three phases for a timeline presentation. What should each phase heading explain?','Agrupa seis eventos en tres fases. ¿Qué debe explicar cada título?','Agrupe seis eventos em três fases. O que cada título deve explicar?'),hint:X('A phase is a change or transition, not just a date range.','Una fase expresa una transición, no solo un rango de fechas.','Uma fase expressa transição, não apenas intervalo de datas.'),solution:X('Each heading should name a pattern or transition, such as “programs move into memory,” and a caption should explain why the change mattered.','Cada título nombra una transición, por ejemplo “los programas pasan a la memoria”, y explica su importancia.','Cada título nomeia uma transição, como “programas passam à memória”, e explica sua importância.'),level:2}]),
lesson('hist8-l4',X('Produce an essay or timeline presentation','Prepara un ensayo o presentación cronológica','Produza ensaio ou apresentação cronológica'),[
X('Choose one format. A short essay can use an introduction with the question and claim, a few evidence-based sections, and a conclusion that answers the question and names a limitation. A timeline presentation can use a title, a small number of dated milestones, explanatory captions, and a closing synthesis. Both formats need citations and readable design.','Elige un formato. Un ensayo breve presenta pregunta y tesis, varias secciones con evidencia y una conclusión con respuesta y límite. Una presentación cronológica usa título, pocos hitos fechados, textos explicativos y síntesis final. Ambos formatos requieren citas y diseño legible.','Escolha um formato. Ensaio curto apresenta pergunta e argumento, algumas seções com evidências e conclusão que responde e aponta limite. Apresentação cronológica usa título, poucos marcos datados, legendas explicativas e síntese final. Ambos exigem citações e design legível.'),
X('Make the work original by choosing your own question, selection of evidence, comparison, and explanation. Paraphrase from understanding, mark direct quotations clearly and sparingly, and cite facts, images, and borrowed interpretations. AI tools are not sources: verify their claims and follow the rules of the assignment or workplace where the project will be used.','Haz el trabajo original con tu propia pregunta, selección de evidencia, comparación y explicación. Parafrasea desde la comprensión, limita y marca citas directas, y cita hechos, imágenes e interpretaciones. Las herramientas de IA no son fuentes: verifica sus afirmaciones y respeta las reglas aplicables.','Torne o trabalho original com pergunta, seleção de evidências, comparação e explicação próprias. Parafraseie com compreensão, use citações diretas com parcimônia e cite fatos, imagens e interpretações. Ferramentas de IA não são fontes: verifique alegações e siga regras aplicáveis.')],
X('A good exhibit label gives the visitor enough context to understand an object without trying to put the whole archive on one wall.','Una buena etiqueta explica un objeto sin intentar poner todo el archivo en una pared.','Boa legenda explica objeto sem tentar colocar todo o arquivo numa parede.'),
[X('Short formats reward selection and synthesis.','Los formatos breves exigen selección y síntesis.','Formatos curtos exigem seleção e síntese.'),X('Originality comes from your question and reasoning, with credit for sources.','La originalidad viene de tu pregunta y razonamiento, con crédito a fuentes.','Originalidade vem de pergunta e raciocínio próprios, com crédito às fontes.')],
[X('Which timeline design is most useful?','¿Qué diseño de cronología es más útil?','Qual design de linha do tempo é mais útil?'),X('A small set of sourced milestones with captions that explain change.','Pocos hitos con fuentes y textos que expliquen el cambio.','Poucos marcos com fontes e legendas que expliquem mudança.'),X('Every date found, without labels.','Todas las fechas encontradas, sin etiquetas.','Todas as datas encontradas, sem rótulos.'),X('Images without sources.','Imágenes sin fuentes.','Imagens sem fontes.'),X('A wall of quotations.','Una pared de citas.','Uma parede de citações.'),'0',X('A selective timeline connects each event to the project question and evidence.','Una cronología selectiva conecta eventos con pregunta y evidencia.','Linha do tempo seletiva conecta eventos à pergunta e às evidências.') ,X('Trying to include every fact and losing the argument.','Incluir todos los datos y perder el argumento.','Incluir todos os fatos e perder o argumento.'),X('Choose milestones that help answer the question; move extra detail to notes.','Elige hitos que respondan la pregunta y deja detalles extra en notas.','Escolha marcos que respondam à pergunta e deixe detalhes extras em notas.')],
[{title:X('Choose the format','Elige el formato','Escolha o formato'),prompt:X('When might a timeline presentation work better than an essay?','¿Cuándo puede funcionar mejor una cronología que un ensayo?','Quando linha do tempo pode funcionar melhor que ensaio?'),hint:X('Think about change over time and visual comparison.','Piensa en cambios temporales y comparación visual.','Pense em mudanças ao longo do tempo e comparação visual.'),solution:X('A timeline suits a question centered on sequence, overlapping milestones, and visible transitions; an essay suits deeper analysis of fewer causes or arguments.','Una cronología sirve para secuencias y transiciones; un ensayo para analizar pocas causas o argumentos con más detalle.','Linha do tempo serve para sequência e transições; ensaio para análise mais profunda de poucas causas ou argumentos.'),level:1},{title:X('Paraphrase responsibly','Parafrasea con responsabilidad','Parafraseie com responsabilidade'),prompt:X('What should you do when notes use a source’s distinctive idea in your own words?','¿Qué debes hacer si tus notas reformulan una idea distintiva de una fuente?','O que fazer ao reformular ideia específica de uma fonte?'),hint:X('Changing words does not remove the source relationship.','Cambiar palabras no elimina la relación con la fuente.','Trocar palavras não elimina relação com a fonte.'),solution:X('Cite the source even when paraphrasing, and make clear which interpretation is yours.','Cita la fuente incluso al parafrasear y distingue tu interpretación.','Cite a fonte mesmo ao parafrasear e deixe clara sua interpretação.'),level:1}],{language:'text',caption:X('A short essay outline','Esquema de ensayo breve','Estrutura de ensaio curto'),source:'Question → Claim → Evidence 1 + reasoning → Evidence 2 + comparison → Conclusion + limits'}),
lesson('hist8-l5',X('Milestones, self-check, and revision','Hitos, autoevaluación y revisión','Marcos, autoavaliação e revisão'),[
X('Use milestones to make progress visible. First approve a question and format; next gather and verify sources; then draft an outline, claim, and selected evidence; create a rough essay or timeline; finally revise citations, clarity, factual accuracy, accessibility, and visual consistency. Leave time for at least one full revision after the first draft.','Usa hitos para hacer visible el avance. Primero define pregunta y formato; luego reúne y verifica fuentes; después redacta esquema, tesis y evidencia; crea un borrador; y revisa citas, claridad, exactitud, accesibilidad y coherencia visual. Reserva tiempo para revisar después del primer borrador.','Use marcos para tornar progresso visível. Primeiro defina pergunta e formato; depois reúna e verifique fontes; em seguida esboce argumento e evidências; crie rascunho; revise citações, clareza, precisão, acessibilidade e consistência visual. Reserve tempo para revisar após o primeiro rascunho.'),
X('Use a simple self-check rubric with five criteria, each scored 0–2: question and scope, evidence and sourcing, historical accuracy, explanation and organization, and communication and attribution. Zero means missing or unsupported; one means partial or uneven; two means clear, accurate, and well supported. A strong project scores at least 8/10 and has no zero for source quality or factual accuracy; revise weak areas before sharing.','Usa una rúbrica de cinco criterios, cada uno de 0 a 2: pregunta y alcance, evidencia y fuentes, exactitud histórica, explicación y organización, comunicación y atribución. Cero es ausente o sin respaldo; uno parcial; dos claro y bien sustentado. Busca al menos 8/10 sin ceros en fuentes o exactitud y revisa debilidades.','Use rubrica simples com cinco critérios, cada um de 0 a 2: pergunta e escopo, evidências e fontes, precisão histórica, explicação e organização, comunicação e atribuição. Zero significa ausente ou sem apoio; um, parcial; dois, claro e bem fundamentado. Busque ao menos 8/10 sem zero em fontes ou precisão e revise pontos fracos.')],
X('A rehearsal checklist catches missed steps while there is still time to fix them.','Una lista de ensayo detecta pasos omitidos mientras aún se pueden corregir.','Uma lista de ensaio detecta etapas esquecidas enquanto ainda há tempo para corrigir.'),
[X('Milestones prevent source work and revision from being squeezed into the end.','Los hitos evitan dejar fuentes y revisión para el final.','Marcos evitam deixar pesquisa e revisão para o fim.'),X('A rubric turns “good work” into checkable criteria.','La rúbrica convierte “buen trabajo” en criterios verificables.','Rubrica transforma “bom trabalho” em critérios verificáveis.')],
[X('A project has polished slides but one unsupported date. What should happen before submission?','Una presentación se ve bien, pero tiene una fecha sin fuente. ¿Qué sigue?','Slides estão bonitos, mas uma data não tem fonte. O que fazer antes de entregar?'),X('Verify or remove the date, cite the supporting source, and review related claims.','Verificar o eliminar la fecha, citar fuente y revisar afirmaciones relacionadas.','Verificar ou remover data, citar fonte e revisar afirmações relacionadas.'),X('Keep it because the slide looks polished.','Dejarla porque la diapositiva se ve bien.','Manter porque o slide está bonito.'),X('Add more animations.','Agregar más animaciones.','Adicionar animações.'),X('Hide the bibliography.','Ocultar bibliografía.','Ocultar bibliografia.'),'0',X('Historical accuracy and sourcing matter more than surface polish.','La exactitud y las fuentes importan más que el acabado superficial.','Precisão histórica e fontes importam mais que acabamento visual.'),X('Treating completion as the same as readiness.','Confundir terminar con estar listo.','Confundir concluir com estar pronto.'),X('Use the rubric to locate gaps, then revise before finalizing.','Usa la rúbrica para hallar vacíos y revisa antes de entregar.','Use a rubrica para localizar lacunas e revise antes de finalizar.')],
[{title:X('Score a draft','Evalúa un borrador','Avalie um rascunho'),prompt:X('A project has a focused question, good sources, accurate facts, but no clear explanation connecting events. What score fits explanation and organization?','Un proyecto tiene pregunta y fuentes buenas, datos exactos, pero no explica conexiones. ¿Qué nota merece explicación?','Projeto tem pergunta focada, boas fontes, fatos corretos, mas não conecta eventos. Que pontuação cabe em explicação?'),hint:X('Use the three rubric levels.','Usa los tres niveles de la rúbrica.','Use três níveis da rubrica.'),solution:X('Likely 1/2: some structure exists, but reasoning and transitions are uneven; add a claim and explain cause, consequence, or comparison.','Probablemente 1/2: hay estructura, pero razonamiento desigual; agrega tesis y explica causas, efectos o comparación.','Provavelmente 1/2: há estrutura, mas raciocínio irregular; acrescente argumento e explique causas, efeitos ou comparação.'),level:2},{title:X('Make a revision plan','Planifica una revisión','Planeje revisão'),prompt:X('List two revisions after a peer says the timeline has too many milestones and unclear labels.','Enumera dos revisiones si alguien dice que hay demasiados hitos y etiquetas confusas.','Liste duas revisões após comentário de que linha do tempo tem marcos demais e rótulos confusos.'),hint:X('Remove or group content and make the story legible.','Elimina o agrupa contenido y aclara la historia.','Remova ou agrupe conteúdo e deixe narrativa clara.'),solution:X('Keep only milestones needed for the question, group them into phases, rewrite captions to state why each mattered, and place source notes beside claims.','Conserva hitos esenciales, agrúpalos, explica su importancia y añade fuentes junto a afirmaciones.','Mantenha marcos essenciais, agrupe-os, explique importância e coloque fontes junto às afirmações.'),level:2}])
];
